dtsPropsFor.Button:
/** Visual register. `danger` is reserved for hard-fail states only — never for a wrong answer. */
  variant?: 'primary' | 'secondary' | 'success' | 'danger';
  /** Leading glyph, rendered before the label. */
  icon?: React.ReactNode;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.NavItem:
/** Bilingual label — Italian first, then English. */
  label: React.ReactNode;
  /** Line-based SVG or glyph, stroke-width 1.5-2. */
  icon?: React.ReactNode;
  /** Marks the current section: gold left rail plus amber gradient fill. */
  active?: boolean;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;

dtsPropsFor.UserLevel:
/** The level readout, e.g. `Livello 7`. */
  badge: React.ReactNode;
  /** Sub-caption under the badge, e.g. `Studente Avanzato`. */
  label?: React.ReactNode;
  /** Enlarges the badge line — used on the profile screen. */
  large?: boolean;
  className?: string;

dtsPropsFor.GlassCard:
/** Optional heading rendered as the card's `h3`. */
  title?: React.ReactNode;
  /** Promotes the card: amber border plus accent glow. */
  featured?: boolean;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.ActionCard:
/** Large glyph shown above the title. */
  icon?: React.ReactNode;
  title: React.ReactNode;
  /** Bilingual supporting copy — Italian first. */
  description?: React.ReactNode;
  /** Promotes the card: amber border plus accent glow. */
  featured?: boolean;
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  className?: string;
  /** Trailing content, typically a `Button`. */
  children?: React.ReactNode;

dtsPropsFor.StatCard:
/** Glyph above the value. */
  icon?: React.ReactNode;
  /** The headline number, rendered at 2.5rem in amber. */
  value: React.ReactNode;
  /** Bilingual caption under the value. */
  label: React.ReactNode;
  className?: string;

dtsPropsFor.LevelProgress:
/** Current level readout, e.g. `7`. */
  level: React.ReactNode;
  /** Bilingual level name shown under the badge. */
  levelName?: React.ReactNode;
  /** Fill percentage, 0-100. Clamped internally. */
  percent: number;
  className?: string;

dtsPropsFor.WeeklyChart:
/** One row per bar. */
  bars?: Array<{ label: React.ReactNode; value: number; display?: React.ReactNode }>;
  /** Upper bound for the track. Defaults to the largest `value`. */
  max?: number;
  /** Shown in italics when `bars` is empty. */
  emptyMessage?: React.ReactNode;
  className?: string;

dtsPropsFor.BadgeCard:
/** Achievement glyph, rendered at 3rem. */
  icon?: React.ReactNode;
  /** English title. */
  title: React.ReactNode;
  /** Italian title, shown under the English one. */
  titleIt?: React.ReactNode;
  description?: React.ReactNode;
  /** Italian description, rendered in italics. */
  descriptionIt?: React.ReactNode;
  /** Unlock date, shown in the mono face in gold. */
  date?: React.ReactNode;
  /** `unlocked` adds gold border and shimmer; `locked` desaturates; `secret` hides further. */
  state?: 'unlocked' | 'locked' | 'secret';
  className?: string;

dtsPropsFor.AchievementToast:
/** Achievement glyph, rendered at 2.5rem with the unlock pop. */
  icon?: React.ReactNode;
  /** Small uppercase eyebrow, e.g. `Traguardo sbloccato`. */
  label?: React.ReactNode;
  /** The achievement name. */
  title: React.ReactNode;
  /** Slides the toast in from the right edge. Off-canvas when false. */
  visible?: boolean;
  className?: string;

dtsPropsFor.ModeCard:
/** Mode glyph, rendered at 2.5rem. */
  icon?: React.ReactNode;
  /** Mode name in the display face. */
  name: React.ReactNode;
  /** Bilingual one-line explanation of the mode. */
  description?: React.ReactNode;
  /** Greys the card out and blocks the hover lift. */
  disabled?: boolean;
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  className?: string;

dtsPropsFor.ActivityList:
/** Panel heading, e.g. `Attività recente / Recent activity`. */
  title?: React.ReactNode;
  items?: Array<{ icon?: React.ReactNode; text: React.ReactNode }>;
  className?: string;
